import { chromium } from 'playwright';
const BASE='https://www.statesideqm.com',THEME='158900125851',route=process.env.ROUTE,label=process.env.LABEL;
const b=await chromium.launch({headless:true});const c=await b.newContext({viewport:{width:1440,height:1000}});const p=await c.newPage();p.setDefaultNavigationTimeout(70000);const req=[];p.on('request',r=>{if(r.resourceType()==='fetch'||r.resourceType()==='xhr')req.push(r.url())});
const u=new URL(route,BASE);u.searchParams.set('preview_theme_id',THEME);const response=await p.goto(u.href,{waitUntil:'domcontentloaded',timeout:70000});await p.waitForLoadState('load',{timeout:16000}).catch(()=>{});await p.waitForTimeout(2600);
const row=await p.evaluate(({req,themeId,label,route})=>{const root=document.querySelector('[data-sqsg]'),view=root?.querySelector('[data-sqsg-view]');const cards=[...(view?.querySelectorAll('.sqsg-card')||[])].map(a=>({label:(a.querySelector('strong')?.textContent||'').replace(/\s+/g,' ').trim(),meta:(a.querySelector('small')?.textContent||'').replace(/\s+/g,' ').trim(),href:a.getAttribute('href')||'',img:!!a.querySelector('img')}));return{label,route,theme:String(window.Shopify?.theme?.id||''),cards,productJson:req.filter(u=>u.includes('/products.json')),productJsonCount:req.filter(u=>u.includes('/products.json')).length,tactical:req.filter(u=>/tactical-packs-bags|pouches-load-carriage|armor-plates-plate-carriers|army-insignia-ranks-awards/.test(u)),previewOk:String(window.Shopify?.theme?.id||'')===themeId}}, {req,themeId:THEME,label,route});
row.http=response?.status()??null;console.log('ROOTCLEAN',JSON.stringify(row));if(row.http!==200||!row.previewOk||row.cards.length<5||row.productJsonCount>1||row.cards.some(x=>/checking|loading/i.test(x.meta)))process.exitCode=2;await c.close();await b.close();